dk_own "$FPA" "$FPS" "$WYA" "$SEC" "$MGA" "$CERTLIB" "$CDS" "$WMA" "$WMS" "$LNS" "$LNR" "$LEAN" "$CSS" "$CST" "$HPS" "$PWI" "$PWS" "$FVS" "$DCS" "$ALS" "$ALT" "$SGS" "$FP2A" "$FP2S" "$FP3A" "$FP3S" "$FBA" "$FB2A" "$FBLR" "$FBL"
