  10 "HP-POINT N=65 class=65a x=1/1 y=0/1 naive-height-num=1 den=1 infinite-order=yes (mP != O for m <= 12, Mazur)" sh_build run_hp
export DK_BASE_RUN="$RUN11"
# arm 11: the Eisenstein eigenvalue 1 + p^3 bent to 1 + p^2 -- every separated a_p moves and the anchor parts at all seven primes
dk_tooth "$PWI" "$MUT" eisbend \
  'let e : i64 = 1i64 + p \* p \* p' \
  'let e : i64 = 1i64 + p * p' \
  11 "PLW-ANCHOR-END met=7 parted=0 verdict=CONCORD" sh_build run_pw
export DK_BASE_RUN="$RUN13"
# arm 13: Jacobsthal's sign bent -- the law at the prime 3 misses the recorded exponent at step 14
dk_tooth "$FVS" "$MUT" jacobend \
