export DK_BASE_RUN="$RUN19B"
# arm 19: the synthetic division's constant step bent (the quadratic's trailing 1 read as -1) -- no integer pole divides, the K = 0 line leaves
dk_tooth "$FTQ" "$MUT" hornerbend \
