# arm 19: the Schur-Cohn branch inverted (inside(p) read as n - inside(Tp) when delta > 0 and inside(Tp) when delta < 0) -- the controls PLANT-LOST, the cells read 0 of 7, the pin leaves
dk_tooth "$FTL2" "$MUT" schurbend \
  'return (delta > 0) ? cnt : n - cnt' \
  'return (delta > 0) ? n - cnt : cnt' \
