export DK_BASE_RUN="$RUN20"
# arm 20: the law's quadratic bent (2(2n^2 + 1) -> 2(2n^2 - 1)): the longitudinal numerator is not divisible at any n, the END verdict leaves
dk_tooth "$FBA" "$MUT" qbbend \
