  'CA[i, 0, k] = n * n * PT[k] + 2 * MD * PTD[k]; CA[i, 1, k] = MD * PTD[k]' \
  20 "FB2-END kat=8 of 8 cells(n=4,8)=16 leading=16 strip-cells=13 strip-leading=13 verdict=MET" sh_build run_fb2
