  'theorem numerator_8 : wscale 4 (zint 4 3) (numerator 4 8) = lawShape 4 8 33 := by decide' \
  21 "KERNEL-ACCEPTED file=<law> theorems=25 errors=0" sh_build run_fbl
dk_teeth_pin 26
